<template><div class="fields"><label>País<select :value="modelValue.pais" @change="update('pais',($event.target as HTMLSelectElement).value)"><option value="PY">Paraguai</option><option value="BR">Brasil</option></select></label><label>Nome do destinatário<input :value="modelValue.nome" @input="update('nome',($event.target as HTMLInputElement).value)" maxlength="120"/></label><label v-for="f in fields" :key="f.key" :class="{wide:f.key==='endereco'}">{{f.label}}<input :value="modelValue[f.key]" @input="update(f.key,($event.target as HTMLInputElement).value)" :maxlength="f.max"/></label></div></template>
<script setup lang="ts">
import type {AddressData} from './types'
const props=defineProps<{modelValue:AddressData}>(),emit=defineEmits<{(e:'update:modelValue',v:AddressData):void}>()
function update(key:string,value:string){emit('update:modelValue',{...props.modelValue,[key]:value})}
const fields:{key:keyof AddressData;label:string;max:number}[]=[{key:'telefone',label:'Telefone',max:40},{key:'cpf',label:'CPF / documento (opcional na impressão)',max:20},{key:'endereco',label:'Rua / endereço (opcional para PY)',max:250},{key:'numero',label:'Número',max:10},{key:'bairro',label:'Bairro',max:60},{key:'complemento',label:'Complemento',max:60},{key:'cidade',label:'Cidade',max:100},{key:'estado',label:'UF / departamento',max:60},{key:'cep',label:'CEP',max:15},{key:'email',label:'E-mail',max:100}]
</script>
<style scoped>.fields{display:grid;grid-template-columns:1fr 1fr;gap:0 15px}label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:600;color:#475569;margin:12px 0}.wide{grid-column:1/-1}input,select{border:1px solid #cbd5e1;border-radius:8px;padding:10px;background:white;color:#172033;min-width:0;font:inherit;font-weight:400}input:focus,select:focus{outline:2px solid #93c5fd}@media(max-width:420px){.fields{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
